/**
 * The curated caption fonts (SPEC section 6): OFL-1.1 files shipped with the
 * app, pinned by sha256 in fonts/fonts.lock.json, with their cmap coverage
 * in fonts/coverage.json (generated by scripts/fetch-fonts.mjs --coverage).
 * Every stack ends in Noto Sans, Noto Sans Devanagari and Noto Color Emoji,
 * so no system font is ever reached: renders look the same on every Mac.
 */
import { statSync } from 'node:fs';
import { join } from 'node:path';
import { err, ok, type Result } from '@taalcut/core';
import coverageJson from '../../fonts/coverage.json';
import lockJson from '../../fonts/fonts.lock.json';
import { FontMissing } from '../errors';
import type { CaptionFontId, CompositionFonts, FontFaceFile, TextMeasurer } from '../types';

/** A curated font, or the emoji font that only ever appears as a fallback. */
export type FontKey = CaptionFontId | 'notoColorEmoji';

export interface FontFileEntry {
  readonly file: string;
  readonly fontId: string;
  readonly family: string;
  /** '400', or a range for variable files: '100 900'. */
  readonly weight: string;
  readonly sha256: string;
  readonly size: number;
  readonly sourceUrl: string;
  readonly upstreamCommit: string;
  readonly spdx: string;
  readonly licenceFile: string;
}

/** Every bundled file, as pinned in fonts.lock.json. */
export const CAPTION_FONT_FILES: readonly FontFileEntry[] = lockJson.files;

/** The fallbacks every stack ends in: Latin, Devanagari, emoji. */
export const FALLBACK_FONTS: readonly FontKey[] = ['notoSans', 'notoSansDevanagari', 'notoColorEmoji'];

/** Design categories, so a reference's caption look maps to the nearest curated font. */
export const FONT_CATEGORIES = ['sans', 'geometric', 'humanist', 'rounded', 'condensed'] as const;
export type FontCategory = (typeof FONT_CATEGORIES)[number];

export const FONT_CATEGORY: Readonly<Record<CaptionFontId, FontCategory>> = {
  notoSans: 'sans',
  notoSansDevanagari: 'sans',
  poppins: 'geometric',
  montserrat: 'geometric',
  mukta: 'humanist',
  hind: 'humanist',
  baloo2: 'rounded',
  anton: 'condensed',
  bebasNeue: 'condensed',
};

type Range = readonly [number, number];

/** Vertical metrics as shares of the em (from the font's first file, OS/2 and hhea). */
export interface FontMetrics {
  readonly capHeight: number;
  readonly ascender: number;
  readonly descender: number;
}

const COVERAGE = coverageJson.fonts as unknown as Record<
  FontKey,
  { readonly ranges: readonly Range[]; readonly metrics: FontMetrics }
>;

export function fontMetrics(font: FontKey): FontMetrics {
  return COVERAGE[font].metrics;
}

/** The font's cmap as inclusive code point ranges, sorted. */
export function fontCoverage(font: FontKey): readonly Range[] {
  return COVERAGE[font]?.ranges ?? [];
}

/** Whether the font has a glyph for the code point (binary search over its ranges). */
export function fontCovers(font: FontKey, codepoint: number): boolean {
  const ranges = fontCoverage(font);
  let low = 0;
  let high = ranges.length - 1;
  while (low <= high) {
    const middle = (low + high) >> 1;
    const [start, end] = ranges[middle]!;
    if (codepoint < start) high = middle - 1;
    else if (codepoint > end) low = middle + 1;
    else return true;
  }
  return false;
}

/** The font itself, then the Noto fallbacks it isn't. */
export function stackKeys(font: CaptionFontId): readonly FontKey[] {
  return [font, ...FALLBACK_FONTS.filter((fallback) => fallback !== font)];
}

export function familyOf(font: FontKey): string {
  const entry = CAPTION_FONT_FILES.find((file) => file.fontId === font);
  if (!entry) throw new RangeError(`No bundled file for font '${font}'`);
  return entry.family;
}

export function filesOf(font: FontKey): readonly FontFileEntry[] {
  return CAPTION_FONT_FILES.filter((file) => file.fontId === font);
}

/** CSS-quoted family names for a curated font, ending in the fallbacks. */
export function fontStack(font: CaptionFontId): readonly string[] {
  return stackKeys(font).map(familyOf);
}

/** The @font-face files a set of fonts needs: each font's own files and every fallback's. */
export function fontFacesFor(fonts: readonly CaptionFontId[]): readonly FontFaceFile[] {
  const keys = new Set<FontKey>(fonts.flatMap((font) => stackKeys(font)));
  return CAPTION_FONT_FILES.filter((file) => keys.has(file.fontId as FontKey)).map((file) => ({
    family: file.family,
    file: file.file,
    weight: file.weight,
    sha256: file.sha256,
  }));
}

/** Weights a file serves: [w, w] for a static file, [min, max] for a variable one. */
export function weightRange(entry: Pick<FontFileEntry, 'weight'>): readonly [number, number] {
  const [low, high] = entry.weight.split(' ').map(Number);
  return [low!, high ?? low!];
}

/**
 * The file CSS font matching would pick for `weight` (CSS Fonts 4, 5.2: above 500 look up first, at 400
 * to 500 look up to 500, then down, else look down first), and the weight to set on a variable file.
 */
export function fileForWeight(
  font: FontKey,
  weight: number,
): { readonly entry: FontFileEntry; readonly weight: number } {
  const files = filesOf(font);
  if (files.length === 0) throw new RangeError(`No bundled file for font '${font}'`);
  const exact = files.find((file) => {
    const [low, high] = weightRange(file);
    return weight >= low && weight <= high;
  });
  if (exact) return { entry: exact, weight };
  const byWeight = [...files].sort((a, b) => weightRange(a)[0] - weightRange(b)[0]);
  const above = byWeight.filter((file) => weightRange(file)[0] > weight);
  const below = byWeight.filter((file) => weightRange(file)[1] < weight).reverse();
  const order =
    weight > 500
      ? [...above, ...below]
      : weight >= 400
        ? [...above.filter((f) => weightRange(f)[0] <= 500), ...below, ...above]
        : [...below, ...above];
  const entry = order[0]!;
  const [low, high] = weightRange(entry);
  return { entry, weight: Math.min(high, Math.max(low, weight)) };
}

function isFile(path: string): boolean {
  try {
    return statSync(path).isFile();
  } catch {
    return false;
  }
}

/** This package's fonts folder (src/captions/fonts.ts → ../../fonts). */
export function packageFontsDir(): string {
  return join(import.meta.dirname, '..', '..', 'fonts');
}

export interface FontDirSources {
  /** A test's or an override's folder: wins when set. */
  readonly explicit?: string;
  /** Contents/Resources/render/fonts in a packaged app. */
  readonly bundledDir?: string;
  /** A checkout: packages/render/fonts. */
  readonly development: boolean;
  /** packages/render, when the caller knows it (bundled code can't use import.meta.dirname). */
  readonly packageDir?: string;
}

/** The first folder that holds every pinned file; render.font_missing names the first missing one. */
export function resolveFontDir(sources: FontDirSources): Result<string> {
  const candidates = [sources.explicit, sources.bundledDir];
  if (sources.development)
    candidates.push(sources.packageDir ? join(sources.packageDir, 'fonts') : packageFontsDir());
  let missing = CAPTION_FONT_FILES[0]!.file;
  for (const dir of candidates) {
    if (!dir) continue;
    const absent = CAPTION_FONT_FILES.find((file) => !isFile(join(dir, file.file)));
    if (!absent) return ok(dir);
    missing = absent.file;
  }
  return err(FontMissing({ font: missing }, { detail: 'No folder holds every pinned caption font' }));
}

/** The fonts a composition may use, from a resolved folder and a measurer over the same files. */
export function createCompositionFonts(dir: string, measurer: TextMeasurer): CompositionFonts {
  return {
    dir,
    measurer,
    stack: (font) => fontStack(font),
    faces: (fonts) => fontFacesFor(fonts),
  };
}
